        [[nodiscard]]
        DebugCaptureFlags GetNativeDebugCaptureFlags()
        {
            DebugCaptureFlags flags = DebugCaptureFlags::None;
            if (JPH::ContactConstraintManager::sDrawContactManifolds)
            {
                flags |= DebugCaptureFlags::ContactManifolds;
            }
            if (JPH::ContactConstraintManager::sDrawContactPointReduction)
            {
                flags |= DebugCaptureFlags::ContactPointReduction;
            }
            if (JPH::ContactConstraintManager::sDrawContactPoint)
            {
                flags |= DebugCaptureFlags::ContactPoints;
            }
            if (JPH::ContactConstraintManager::sDrawSupportingFaces)
            {
                flags |= DebugCaptureFlags::ContactSupportingFaces;
            }
            if (JPH::PhysicsSystem::sDrawMotionQualityLinearCast)
            {
                flags |= DebugCaptureFlags::MotionQualityLinearCasts;
            }
            if (JPH::Shape::sDrawSubmergedVolumes)
            {
                flags |= DebugCaptureFlags::SubmergedVolumes;
            }
            if (JPH::CharacterVirtual::sDrawConstraints)
            {
                flags |= DebugCaptureFlags::VirtualCharacterConstraints;
            }
            if (JPH::CharacterVirtual::sDrawStickToFloor)
            {
                flags |= DebugCaptureFlags::VirtualCharacterStickToFloor;
            }
            if (JPH::CharacterVirtual::sDrawSupportingVolume)
            {
                flags |= DebugCaptureFlags::VirtualCharacterSupportingVolumes;
            }
            if (JPH::CharacterVirtual::sDrawWalkStairs)
            {
                flags |= DebugCaptureFlags::VirtualCharacterWalkStairs;
            }
            return flags;
        }

