        class SnapshotStateFilter final
            : public JPH::StateRecorderFilter
        {
        public:
            SnapshotStateFilter(
                const AZStd::span<const AZ::u32> bodyIds,
                const AZStd::span<const AZ::u64> constraintAddresses,
                const AZ::u32 bodyStateCount,
                const AZ::u32 constraintStateCount)
                : m_bodyIds(bodyIds)
                , m_constraintAddresses(constraintAddresses)
                , m_bodyStateCount(bodyStateCount)
                , m_constraintStateCount(constraintStateCount)
            {
            }

            [[nodiscard]]
            JPH::uint GetNumBodiesToSave() const override
            {
                return m_bodyStateCount;
            }

            [[nodiscard]]
            JPH::uint GetNumConstraintsToSave() const override
            {
                return m_constraintStateCount;
            }

            [[nodiscard]]
            bool ShouldSaveBody(const JPH::Body& body) const override
            {
                return ContainsBody(body.GetID());
            }

            [[nodiscard]]
            bool ShouldSaveConstraint(const JPH::Constraint& constraint) const override
            {
                const AZ::u64 address = reinterpret_cast<AZ::u64>(&constraint);
                return AZStd::binary_search(
                    m_constraintAddresses.begin(),
                    m_constraintAddresses.end(),
                    address);
            }

            [[nodiscard]]
            bool ShouldSaveContact(
                const JPH::BodyID& firstBodyId,
                const JPH::BodyID& secondBodyId) const override
            {
                const AZ::u32 firstId = firstBodyId.GetIndexAndSequenceNumber();
                const AZ::u32 secondId = secondBodyId.GetIndexAndSequenceNumber();
                return AZStd::binary_search(
                    m_bodyIds.begin(),
                    m_bodyIds.end(),
                    AZStd::min(firstId, secondId));
            }

            [[nodiscard]]
            bool ShouldRestoreContact(
                const JPH::BodyID& firstBodyId,
                const JPH::BodyID& secondBodyId) const override
            {
                return ShouldSaveContact(firstBodyId, secondBodyId);
            }

        private:
            [[nodiscard]]
            bool ContainsBody(const JPH::BodyID bodyId) const
            {
                return AZStd::binary_search(
                    m_bodyIds.begin(),
                    m_bodyIds.end(),
                    bodyId.GetIndexAndSequenceNumber());
            }

            AZStd::span<const AZ::u32> m_bodyIds;
            AZStd::span<const AZ::u64> m_constraintAddresses;
            AZ::u32 m_bodyStateCount = 0;
            AZ::u32 m_constraintStateCount = 0;
        };

        [[nodiscard]]
        bool IsSupportedLayer(
            const ObjectLayer layer,
            const size_t layerCount)
        {
            return layer && layer.GetValue() <= layerCount;
        }

        [[nodiscard]]
        bool IsValidVirtualCharacterUpdateConfiguration(
            const VirtualCharacterUpdateConfiguration& configuration)
        {
            return configuration.m_gravity.IsFinite()
                && configuration.m_stickToFloorStepDown.IsFinite()
                && configuration.m_walkStairsStepDownExtra.IsFinite()
                && configuration.m_walkStairsStepUp.IsFinite()
                && AZ::IsFiniteFloat(configuration.m_walkStairsCosAngleForwardContact)
                && configuration.m_walkStairsCosAngleForwardContact >= -1.0f
                && configuration.m_walkStairsCosAngleForwardContact <= 1.0f
                && AZ::IsFiniteFloat(configuration.m_walkStairsMinimumStepForward)
                && configuration.m_walkStairsMinimumStepForward >= 0.0f
                && AZ::IsFiniteFloat(configuration.m_walkStairsStepForwardTest)
                && configuration.m_walkStairsStepForwardTest >= 0.0f;
        }

        [[nodiscard]]
        bool IsValidVirtualCharacterRuntimeConfiguration(
            const VirtualCharacterRuntimeConfiguration& configuration)
        {
            return configuration.m_shapeOffset.IsFinite()
                && configuration.m_supportingPlaneNormal.IsFinite()
                && !configuration.m_supportingPlaneNormal.IsZero()
                && configuration.m_up.IsFinite()
                && !configuration.m_up.IsZero()
                && AZ::IsFiniteFloat(configuration.m_hitReductionCosMaximumAngle)
                && configuration.m_hitReductionCosMaximumAngle >= -1.0f
                && configuration.m_hitReductionCosMaximumAngle <= 1.0f
                && AZ::IsFiniteFloat(configuration.m_mass)
                && configuration.m_mass > 0.0f
                && AZ::IsFiniteFloat(configuration.m_maximumSlopeAngle)
                && configuration.m_maximumSlopeAngle >= 0.0f
                && configuration.m_maximumSlopeAngle <= AZ::Constants::HalfPi
                && AZ::IsFiniteFloat(configuration.m_maximumStrength)
                && configuration.m_maximumStrength >= 0.0f
                && AZ::IsFiniteFloat(configuration.m_penetrationRecoverySpeed)
                && configuration.m_penetrationRecoverySpeed >= 0.0f
                && configuration.m_penetrationRecoverySpeed <= 1.0f
                && AZ::IsFiniteFloat(configuration.m_supportingPlaneDistance)
                && configuration.m_maximumHitCount > 0;
        }

        [[nodiscard]]
        bool IsValidVirtualCharacterStairConfiguration(
            const VirtualCharacterStairConfiguration& configuration)
        {
            return configuration.m_stepDownExtra.IsFinite()
                && configuration.m_stepForward.IsFinite()
                && configuration.m_stepForwardTest.IsFinite()
                && configuration.m_stepUp.IsFinite()
                && AZ::IsFiniteFloat(configuration.m_deltaTime)
                && configuration.m_deltaTime > 0.0f;
        }

