        [[nodiscard]]
        bool SupportsSubmergedVolume(const JPH::Shape& shape)
        {
            switch (shape.GetSubType())
            {
            case JPH::EShapeSubType::HeightField:
            case JPH::EShapeSubType::Mesh:
            case JPH::EShapeSubType::Plane:
                return false;

            case JPH::EShapeSubType::MutableCompound:
            case JPH::EShapeSubType::StaticCompound:
            {
                const auto& compound = static_cast<const JPH::CompoundShape&>(shape);
                for (JPH::uint childIndex = 0; childIndex < compound.GetNumSubShapes(); ++childIndex)
                {
                    if (!SupportsSubmergedVolume(*compound.GetSubShape(childIndex).mShape))
                    {
                        return false;
                    }
                }
                return true;
            }

            case JPH::EShapeSubType::OffsetCenterOfMass:
            case JPH::EShapeSubType::RotatedTranslated:
            case JPH::EShapeSubType::Scaled:
                return SupportsSubmergedVolume(
                    *static_cast<const JPH::DecoratedShape&>(shape).GetInnerShape());

            default:
                return true;
            }
        }

        [[nodiscard]]
        bool HasStateFlag(
            const StateSnapshotFlags flags,
            const StateSnapshotFlags flag)
        {
            return (flags & flag) != StateSnapshotFlags::None;
        }

        [[nodiscard]]
        JPH::EStateRecorderState ToNativeStateFlags(
            const StateSnapshotFlags flags)
        {
            JPH::EStateRecorderState nativeFlags = JPH::EStateRecorderState::None;
            if (HasStateFlag(flags, StateSnapshotFlags::Global))
            {
                nativeFlags |= JPH::EStateRecorderState::Global;
            }
            if (HasStateFlag(flags, StateSnapshotFlags::Bodies))
            {
                nativeFlags |= JPH::EStateRecorderState::Bodies;
            }
            if (HasStateFlag(flags, StateSnapshotFlags::Contacts))
            {
                nativeFlags |= JPH::EStateRecorderState::Contacts;
            }
            if (HasStateFlag(flags, StateSnapshotFlags::Constraints))
            {
                nativeFlags |= JPH::EStateRecorderState::Constraints;
            }
            return nativeFlags;
        }

