        AZ_UNUSED(debugDrawSize);
        return false;
#else
        AZStd::lock_guard lock(m_mutex);
        const ConstraintSlot* slot = FindConstraint(constraintHandle);
        if (!slot)
        {
            return false;
        }

        debugDrawSize = slot->m_constraint->GetDrawConstraintSize();
        return true;
