    bool World::GetBodyCollisionGroup(
        const BodyHandle bodyHandle,
        CollisionGroupConfiguration& collisionGroup) const
    {
        AZStd::lock_guard lock(m_mutex);
        const BodySlot* slot = FindBody(bodyHandle);
        if (!slot)
        {
            return false;
        }

        JPH::BodyLockRead bodyLock(m_physicsSystem.GetBodyLockInterface(), slot->m_bodyId);
        if (!bodyLock.Succeeded())
        {
            return false;
        }

        const JPH::CollisionGroup& nativeGroup = bodyLock.GetBody().GetCollisionGroup();
        collisionGroup = {
            .m_filterHandle = slot->m_groupFilterHandle,
            .m_groupId = CollisionGroupId{nativeGroup.GetGroupID()},
            .m_subGroupId = CollisionSubGroupId{nativeGroup.GetSubGroupID()},
        };
        return true;
    }

