    bool World::GetBodyBounds(
        const BodyHandle bodyHandle,
        BroadPhaseAabb& bounds) const
    {
        AZStd::lock_guard lock(m_mutex);
        const BodySlot* slot = FindBody(bodyHandle);
        if (!slot)
        {
            return false;
        }

        JPH::BodyLockRead bodyLock(m_physicsSystem.GetBodyLockInterface(), slot->m_bodyId);
        if (!bodyLock.Succeeded())
        {
            return false;
        }

        const JPH::AABox& nativeBounds = bodyLock.GetBody().GetWorldSpaceBounds();
        if (!nativeBounds.IsValid())
        {
            return false;
        }

        bounds = {
            .m_center = FromNativePosition(
                JPH::RVec3(nativeBounds.GetCenter()),
                m_configuration.m_origin),
            .m_halfExtents = FromNativeVector(nativeBounds.GetExtent()),
        };
        return true;
    }

    bool World::GetBodySubmergedVolume(
        const BodyHandle bodyHandle,
        const WorldPosition& surfacePosition,
        const AZ::Vector3& surfaceNormal,
        SubmergedVolumeResult& result) const
    {
        AZStd::lock_guard lock(m_mutex);
        const BodySlot* slot = FindBody(bodyHandle);
        if (!slot
            || !IsFinite(surfacePosition)
            || !surfaceNormal.IsFinite()
            || surfaceNormal.IsZero())
        {
            return false;
        }

        JPH::BodyLockRead bodyLock(m_physicsSystem.GetBodyLockInterface(), slot->m_bodyId);
        if (!bodyLock.Succeeded())
        {
            return false;
        }

        const JPH::Body& body = bodyLock.GetBody();
        if (!SupportsSubmergedVolume(*body.GetShape()))
        {
            return false;
        }

        float totalVolume = 0.0f;
        float submergedVolume = 0.0f;
        JPH::Vec3 relativeCenterOfBuoyancy = JPH::Vec3::sZero();
        body.GetSubmergedVolume(
            ToNativePosition(surfacePosition, m_configuration.m_origin),
            ToNativeVector(surfaceNormal.GetNormalized()),
            totalVolume,
            submergedVolume,
            relativeCenterOfBuoyancy);
        if (!AZ::IsFiniteFloat(totalVolume)
            || !AZ::IsFiniteFloat(submergedVolume)
            || !IsFinite(relativeCenterOfBuoyancy))
        {
            return false;
        }

        const WorldPosition centerOfMassPosition =
            FromNativePosition(body.GetCenterOfMassPosition(), m_configuration.m_origin);
        result = {
            .m_centerOfBuoyancy = FromNativePosition(
                JPH::RVec3(relativeCenterOfBuoyancy),
                centerOfMassPosition),
            .m_submergedVolume = submergedVolume,
            .m_totalVolume = totalVolume,
        };
        return true;
    }

    bool World::GetBodySurfaceNormal(
        const BodyHandle bodyHandle,
        const SubShapeId subShapeId,
        const WorldPosition& surfacePosition,
        AZ::Vector3& normal) const
    {
        AZStd::lock_guard lock(m_mutex);
        const BodySlot* slot = FindBody(bodyHandle);
        if (!slot || !IsFinite(surfacePosition))
        {
            return false;
        }

        JPH::BodyLockRead bodyLock(m_physicsSystem.GetBodyLockInterface(), slot->m_bodyId);
        if (!bodyLock.Succeeded())
        {
            return false;
        }

        const JPH::Body& body = bodyLock.GetBody();
        if (!IsPotentiallyValidSubShapeId(*body.GetShape(), subShapeId))
        {
            return false;
        }

        JPH::SubShapeID nativeSubShapeId;
        nativeSubShapeId.SetValue(subShapeId.GetValue());
        normal = FromNativeVector(
            body.GetWorldSpaceSurfaceNormal(
                nativeSubShapeId,
                ToNativePosition(surfacePosition, m_configuration.m_origin)));
        return normal.IsFinite();
    }

    bool World::GetBodyMaterial(
        const BodyHandle bodyHandle,
        const SubShapeId subShapeId,
        MaterialHandle& materialHandle) const
    {
        AZStd::lock_guard lock(m_mutex);
        const BodySlot* slot = FindBody(bodyHandle);
        if (!slot)
        {
            return false;
        }

        JPH::BodyLockRead bodyLock(m_physicsSystem.GetBodyLockInterface(), slot->m_bodyId);
        if (!bodyLock.Succeeded())
        {
            return false;
        }

        const JPH::Shape* shape = bodyLock.GetBody().GetShape();
        if (!IsPotentiallyValidSubShapeId(*shape, subShapeId))
        {
            return false;
        }

        JPH::SubShapeID nativeSubShapeId;
        nativeSubShapeId.SetValue(subShapeId.GetValue());
        materialHandle = m_system.FindMaterialHandle(shape->GetMaterial(nativeSubShapeId));
        return true;
    }

