    bool World::UpdateBodyRuntimeConfiguration(
        const BodyHandle bodyHandle,
        const BodyRuntimeConfiguration& configuration,
        const bool activate)
    {
        AZStd::lock_guard lock(m_mutex);
        BodySlot* slot = FindBody(bodyHandle);
        const MassPropertiesConfiguration& mass = configuration.m_massProperties;
        const AZ::u8 allowedDofs = static_cast<AZ::u8>(configuration.m_allowedDofs);
        constexpr AZ::u8 allAllowedDofs = static_cast<AZ::u8>(AllowedDofs::All);
        const bool validAllowedDofs = allowedDofs != 0
            && (allowedDofs & static_cast<AZ::u8>(~allAllowedDofs)) == 0;
        const bool validMotionQuality = configuration.m_motionQuality == MotionQuality::Continuous
            || configuration.m_motionQuality == MotionQuality::Discrete;
        bool validMass = mass.m_mode == MassPropertiesMode::CalculateMassAndInertia;
        if (mass.m_mode == MassPropertiesMode::CalculateInertia)
        {
            validMass = AZ::IsFiniteFloat(mass.m_mass) && mass.m_mass > 0.0f;
        }
        else if (mass.m_mode == MassPropertiesMode::Provided)
        {
            const AZ::Matrix3x3& inertia = mass.m_inertia;
            validMass = inertia.IsFinite()
                && inertia.IsClose(inertia.GetTranspose())
                && inertia.GetElement(0, 0) > 0.0f
                && inertia.GetElement(0, 0) * inertia.GetElement(1, 1)
                    - inertia.GetElement(0, 1) * inertia.GetElement(1, 0) > 0.0f
                && inertia.GetDeterminant() > 0.0f
                && AZ::IsFiniteFloat(mass.m_mass)
                && mass.m_mass > 0.0f;
        }

        if (!slot
            || slot->m_kind != BodyKind::Rigid
            || slot->m_motionType == MotionType::Static
            || !validAllowedDofs
            || !validMotionQuality
            || !validMass
            || !AZ::IsFiniteFloat(mass.m_inertiaMultiplier)
            || mass.m_inertiaMultiplier <= 0.0f
            || !AZ::IsFiniteFloat(configuration.m_angularDamping)
            || configuration.m_angularDamping < 0.0f
            || !AZ::IsFiniteFloat(configuration.m_friction)
            || configuration.m_friction < 0.0f
            || !AZ::IsFiniteFloat(configuration.m_gravityFactor)
            || !AZ::IsFiniteFloat(configuration.m_linearDamping)
            || configuration.m_linearDamping < 0.0f
            || !AZ::IsFiniteFloat(configuration.m_maximumAngularVelocity)
            || configuration.m_maximumAngularVelocity < 0.0f
            || !AZ::IsFiniteFloat(configuration.m_maximumLinearVelocity)
            || configuration.m_maximumLinearVelocity < 0.0f
            || !AZ::IsFiniteFloat(configuration.m_restitution)
            || configuration.m_restitution < 0.0f
            || configuration.m_restitution > 1.0f)
        {
            return false;
        }

        {
            JPH::BodyLockWrite bodyLock(m_physicsSystem.GetBodyLockInterface(), slot->m_bodyId);
            if (!bodyLock.Succeeded())
            {
                return false;
            }

            JPH::Body& body = bodyLock.GetBody();
            JPH::MotionProperties* motionProperties = body.GetMotionProperties();
            if (!AdvanceBodyConfigurationRevision(*slot))
            {
                return false;
            }

            JPH::MassProperties nativeMassProperties;
            if (mass.m_mode == MassPropertiesMode::Provided)
            {
                nativeMassProperties.mMass = mass.m_mass;
                nativeMassProperties.mInertia = ToNativeInertia(mass.m_inertia);
            }
            else
            {
                nativeMassProperties = body.GetShape()->GetMassProperties();
                if (mass.m_mode == MassPropertiesMode::CalculateInertia)
                {
                    nativeMassProperties.ScaleToMass(mass.m_mass);
                }
                nativeMassProperties.mInertia *= mass.m_inertiaMultiplier;
                nativeMassProperties.mInertia(3, 3) = 1.0f;
            }

            motionProperties->SetMassProperties(
                static_cast<JPH::EAllowedDOFs>(static_cast<AZ::u8>(configuration.m_allowedDofs)),
                nativeMassProperties);
            motionProperties->SetAngularDamping(configuration.m_angularDamping);
            motionProperties->SetGravityFactor(configuration.m_gravityFactor);
            motionProperties->SetLinearDamping(configuration.m_linearDamping);
            motionProperties->SetMaxAngularVelocity(configuration.m_maximumAngularVelocity);
            motionProperties->SetMaxLinearVelocity(configuration.m_maximumLinearVelocity);
            motionProperties->SetNumPositionStepsOverride(configuration.m_positionStepCount);
            motionProperties->SetNumVelocityStepsOverride(configuration.m_velocityStepCount);
            body.SetAllowSleeping(configuration.m_allowSleeping);
            body.SetApplyGyroscopicForce(configuration.m_applyGyroscopicForce);
            body.SetCollideKinematicVsNonDynamic(configuration.m_collideKinematicVsNonDynamic);
            body.SetEnhancedInternalEdgeRemoval(configuration.m_enhancedInternalEdgeRemoval);
            body.SetFriction(configuration.m_friction);
            body.SetIsSensor(configuration.m_isSensor);
            body.SetRestitution(configuration.m_restitution);
            body.SetUseManifoldReduction(configuration.m_useManifoldReduction);
        }

        m_physicsSystem.GetBodyInterface().SetMotionQuality(
            slot->m_bodyId,
            ToNativeMotionQuality(configuration.m_motionQuality));
        if (activate && slot->m_motionType != MotionType::Static)
        {
            m_physicsSystem.GetBodyInterface().ActivateBody(slot->m_bodyId);
        }
        return true;
    }

