    bool World::SetBodyShape(
        const BodyHandle bodyHandle,
        const ShapeHandle shapeHandle,
        const bool updateMassProperties,
        const bool activate)
    {
        AZStd::lock_guard lock(m_mutex);
        BodySlot* bodySlot = FindBody(bodyHandle);
        ShapeSlot* shapeSlot = FindShape(shapeHandle);
        if (!bodySlot
            || bodySlot->m_kind != BodyKind::Rigid
            || !shapeSlot
            || (bodySlot->m_motionType != MotionType::Static && shapeSlot->m_shape->MustBeStatic()))
        {
            return false;
        }
        if (!AdvanceBodyConfigurationRevision(*bodySlot))
        {
            return false;
        }

        ShapeSlot* previousShapeSlot = FindShape(bodySlot->m_shapeHandle);
        AZ_Assert(previousShapeSlot && previousShapeSlot->m_bodyCount > 0, "Body shape ownership is inconsistent.");
        m_physicsSystem.GetBodyInterface().SetShape(
            bodySlot->m_bodyId,
            shapeSlot->m_shape.GetPtr(),
            updateMassProperties,
            ToNativeActivation(activate));
        --previousShapeSlot->m_bodyCount;
        ++shapeSlot->m_bodyCount;
        bodySlot->m_shapeHandle = shapeHandle;
        return true;
    }

    bool World::SetBodyMotionType(
        const BodyHandle bodyHandle,
        const MotionType motionType,
        const bool activate)
    {
        AZStd::lock_guard lock(m_mutex);
        BodySlot* bodySlot = FindBody(bodyHandle);
        if (!bodySlot
            || bodySlot->m_kind != BodyKind::Rigid
            || bodySlot->m_characterHandle
            || bodySlot->m_virtualCharacterHandle
            || motionType == MotionType::None)
        {
            return false;
        }

        const ShapeSlot* shapeSlot = FindShape(bodySlot->m_shapeHandle);
        if (!shapeSlot || (motionType != MotionType::Static && shapeSlot->m_shape->MustBeStatic()))
        {
            return false;
        }

        if (motionType != MotionType::Static)
        {
            JPH::BodyLockRead bodyLock(m_physicsSystem.GetBodyLockInterface(), bodySlot->m_bodyId);
            if (!bodyLock.Succeeded() || !bodyLock.GetBody().CanBeKinematicOrDynamic())
            {
                return false;
            }
        }
        if (!AdvanceBodyConfigurationRevision(*bodySlot))
        {
            return false;
        }

        m_physicsSystem.GetBodyInterface().SetMotionType(
            bodySlot->m_bodyId,
            ToNativeMotionType(motionType),
            ToNativeActivation(activate));
        bodySlot->m_motionType = motionType;
        return true;
    }

    bool World::SetBodyObjectLayer(
        const BodyHandle bodyHandle,
        const ObjectLayer objectLayer)
    {
        AZStd::lock_guard lock(m_mutex);
        BodySlot* bodySlot = FindBody(bodyHandle);
        if (!bodySlot
            || bodySlot->m_characterHandle
            || !IsSupportedLayer(objectLayer, m_configuration.m_objectLayers.size()))
        {
            return false;
        }
        if (!AdvanceBodyConfigurationRevision(*bodySlot))
        {
            return false;
        }

        m_physicsSystem.GetBodyInterface().SetObjectLayer(bodySlot->m_bodyId, ToNativeObjectLayer(objectLayer));
        return true;
    }

    bool World::SetBodyCollisionGroup(
        const BodyHandle bodyHandle,
        const CollisionGroupConfiguration& collisionGroup,
        const bool activate)
    {
        AZStd::lock_guard lock(m_mutex);
        BodySlot* bodySlot = FindBody(bodyHandle);
        if (!bodySlot)
        {
            return false;
        }

        JPH::CollisionGroup nativeCollisionGroup;
        if (!m_system.AcquireCollisionGroup(collisionGroup, nativeCollisionGroup, m_handle))
        {
            return false;
        }
        if (!AdvanceBodyConfigurationRevision(*bodySlot))
        {
            m_system.ReleaseGroupFilter(collisionGroup.m_filterHandle, m_handle);
            return false;
        }

        JPH::BodyInterface& bodyInterface = m_physicsSystem.GetBodyInterface();
        bodyInterface.SetCollisionGroup(bodySlot->m_bodyId, nativeCollisionGroup);
        bodyInterface.InvalidateContactCache(bodySlot->m_bodyId);
        if (activate && bodySlot->m_motionType != MotionType::Static)
        {
            bodyInterface.ActivateBody(bodySlot->m_bodyId);
        }

        m_system.ReleaseGroupFilter(bodySlot->m_groupFilterHandle, m_handle);
        bodySlot->m_groupFilterHandle = collisionGroup.m_filterHandle;
        return true;
    }

    bool World::RaycastShapeClosest(
        const ShapeRaycastRequest& request,
        ShapeRaycastHit& hit) const
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::RaycastShapeClosest");
        PerformanceQueryScope statisticsScope(
            IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Queries),
            m_performanceStatistics);
        DeterministicWorldQueryLock lock(m_mutex);
        const ShapeSlot* shapeSlot = FindShape(request.m_shapeHandle);
        if (!shapeSlot
            || !request.m_start.IsFinite()
            || !request.m_displacement.IsFinite()
            || request.m_displacement.IsZero())
        {
            return false;
        }

        JPH::RayCastSettings settings;
        if (!ApplyBackFaceMode(
                request.m_convexBackFaceMode,
                settings.mBackFaceModeConvex)
            || !ApplyBackFaceMode(
                request.m_triangleBackFaceMode,
                settings.mBackFaceModeTriangles))
        {
            return false;
        }
        settings.mTreatConvexAsSolid = request.m_treatConvexAsSolid;

        const JPH::RayCast ray(
            ToNativeVector(request.m_start) - shapeSlot->m_shape->GetCenterOfMass(),
            ToNativeVector(request.m_displacement));
        CanonicalClosestHitCollector<JPH::CastRayCollector> collector;
        const StandaloneShapeFilterAdapter filter(request.m_shapeHandle, request.m_filter);
        shapeSlot->m_shape->CastRay(
            ray,
            settings,
            JPH::SubShapeIDCreator(),
            collector,
            filter);
        const bool found = collector.HadHit()
            && BuildShapeRaycastHit(
                *shapeSlot->m_shape,
                request,
                collector.m_hit,
                hit);
        statisticsScope.SetCounts(1, 0, found);
        return found;
    }

    QueryResult World::RaycastShapeAll(
        const ShapeRaycastRequest& request,
        const AZStd::span<ShapeRaycastHit> hits) const
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::RaycastShapeAll");
        PerformanceQueryScope statisticsScope(
            IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Queries),
            m_performanceStatistics);
        DeterministicWorldQueryLock lock(m_mutex);
        const ShapeSlot* shapeSlot = FindShape(request.m_shapeHandle);
        if (!shapeSlot
            || !request.m_start.IsFinite()
            || !request.m_displacement.IsFinite()
            || request.m_displacement.IsZero())
        {
            return {};
        }

        JPH::RayCastSettings settings;
        if (!ApplyBackFaceMode(
                request.m_convexBackFaceMode,
                settings.mBackFaceModeConvex)
            || !ApplyBackFaceMode(
                request.m_triangleBackFaceMode,
                settings.mBackFaceModeTriangles))
        {
            return {};
        }
        settings.mTreatConvexAsSolid = request.m_treatConvexAsSolid;

        const JPH::RayCast ray(
            ToNativeVector(request.m_start) - shapeSlot->m_shape->GetCenterOfMass(),
            ToNativeVector(request.m_displacement));
        JPH::AllHitCollisionCollector<JPH::CastRayCollector> collector;
        const StandaloneShapeFilterAdapter filter(request.m_shapeHandle, request.m_filter);
        shapeSlot->m_shape->CastRay(
            ray,
            settings,
            JPH::SubShapeIDCreator(),
            collector,
            filter);
        AZStd::sort(
            collector.mHits.begin(),
            collector.mHits.end(),
            [](const JPH::RayCastResult& first, const JPH::RayCastResult& second)
            {
                return IsCanonicalCastHitLess(first, second);
            });

        QueryResult result = {
            .m_requiredHitCount = aznumeric_cast<AZ::u32>(collector.mHits.size()),
        };
        const size_t hitCount = AZStd::min(hits.size(), collector.mHits.size());
        for (size_t hitIndex = 0; hitIndex < hitCount; ++hitIndex)
        {
            if (BuildShapeRaycastHit(
                    *shapeSlot->m_shape,
                    request,
                    collector.mHits[hitIndex],
                    hits[result.m_hitCount]))
            {
                ++result.m_hitCount;
            }
        }
        statisticsScope.SetCounts(1, collector.mHits.size(), result.m_hitCount);
        return result;
    }

    QueryResult World::CollideShapePoint(
        const ShapeHandle shapeHandle,
        const AZ::Vector3& localPosition,
        const IQueryFilter* filter,
        const AZStd::span<ShapePointHit> hits) const
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::CollideShapePoint");
        PerformanceQueryScope statisticsScope(
            IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Queries),
            m_performanceStatistics);
        DeterministicWorldQueryLock lock(m_mutex);
        const ShapeSlot* shapeSlot = FindShape(shapeHandle);
        if (!shapeSlot || !localPosition.IsFinite())
        {
            return {};
        }

        JPH::AllHitCollisionCollector<JPH::CollidePointCollector> collector;
        const StandaloneShapeFilterAdapter nativeFilter(shapeHandle, filter);
        shapeSlot->m_shape->CollidePoint(
            ToNativeVector(localPosition) - shapeSlot->m_shape->GetCenterOfMass(),
            JPH::SubShapeIDCreator(),
            collector,
            nativeFilter);
        AZStd::sort(
            collector.mHits.begin(),
            collector.mHits.end(),
            [](const JPH::CollidePointResult& first, const JPH::CollidePointResult& second)
            {
                return first.mSubShapeID2.GetValue() < second.mSubShapeID2.GetValue();
            });

        QueryResult result = {
            .m_requiredHitCount = aznumeric_cast<AZ::u32>(collector.mHits.size()),
        };
        result.m_hitCount = aznumeric_cast<AZ::u32>(AZStd::min(hits.size(), collector.mHits.size()));
        for (AZ::u32 hitIndex = 0; hitIndex < result.m_hitCount; ++hitIndex)
        {
            const JPH::SubShapeID nativeSubShapeId = collector.mHits[hitIndex].mSubShapeID2;
            hits[hitIndex] = {
                .m_materialHandle = m_system.FindMaterialHandle(
                    shapeSlot->m_shape->GetMaterial(nativeSubShapeId)),
                .m_subShapeId = SubShapeId(nativeSubShapeId.GetValue()),
            };
        }
        statisticsScope.SetCounts(1, collector.mHits.size(), result.m_hitCount);
        return result;
    }

