    QueryResult World::CollideTransformedShapePoint(
        const TransformedShape& shape,
        const WorldPosition& position,
        const IQueryFilter* filter,
        const AZStd::span<OverlapHit> hits) const
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::CollideTransformedShapePoint");
        PerformanceQueryScope statisticsScope(
            IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Queries),
            m_performanceStatistics);
        DeterministicWorldQueryLock lock(m_mutex);
        const Internal::TransformedShapeLeaseRecord* record = GetTransformedShapeRecord(shape);
        if (!record
            || !IsFinite(position)
            || (filter && !filter->ShouldIncludeBody(record->m_bodyHandle)))
        {
            return {};
        }

        JPH::AllHitCollisionCollector<JPH::CollidePointCollector> collector;
        const StandaloneShapeFilterAdapter nativeFilter(
            record->m_shapeHandle,
            filter,
            record->m_bodyHandle);
        record->m_nativeShape.CollidePoint(
            ToNativePosition(position, record->m_worldOrigin),
            collector,
            nativeFilter);
        AZStd::sort(
            collector.mHits.begin(),
            collector.mHits.end(),
            [](const JPH::CollidePointResult& first, const JPH::CollidePointResult& second)
            {
                return first.mSubShapeID2.GetValue() < second.mSubShapeID2.GetValue();
            });

        QueryResult result = {
            .m_requiredHitCount = aznumeric_cast<AZ::u32>(collector.mHits.size()),
        };
        result.m_hitCount = aznumeric_cast<AZ::u32>(AZStd::min(hits.size(), collector.mHits.size()));
        for (AZ::u32 hitIndex = 0; hitIndex < result.m_hitCount; ++hitIndex)
        {
            const JPH::SubShapeID subShapeId = collector.mHits[hitIndex].mSubShapeID2;
            hits[hitIndex] = {
                .m_bodyHandle = record->m_bodyHandle,
                .m_materialHandle = m_system.FindMaterialHandle(record->m_nativeShape.GetMaterial(subShapeId)),
                .m_shapeHandle = record->m_shapeHandle,
                .m_subShapeId = SubShapeId(subShapeId.GetValue()),
            };
        }
        statisticsScope.SetCounts(1, collector.mHits.size(), result.m_hitCount);
        return result;
    }

