    QueryResult World::RaycastAll(
        const RaycastRequest& request,
        const AZStd::span<RaycastHit> hits) const
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::RaycastAll");
        PerformanceQueryScope statisticsScope(
            IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Queries),
            m_performanceStatistics);
        DeterministicWorldQueryLock lock(m_mutex);
        if (!IsFinite(request.m_start)
            || !request.m_displacement.IsFinite()
            || request.m_displacement.IsZero()
            || (request.m_filter.m_collisionLayer
                && !IsSupportedLayer(request.m_filter.m_collisionLayer, m_configuration.m_objectLayers.size())))
        {
            return {};
        }

        const JPH::RRayCast ray(
            ToNativePosition(request.m_start, m_configuration.m_origin),
            ToNativeVector(request.m_displacement));
        JPH::AllHitCollisionCollector<JPH::CastRayCollector> collector;
        const auto cast =
            [&](const JPH::BodyFilter& bodyFilter, const JPH::ShapeFilter& shapeFilter)
            {
                if (request.m_filter.m_collisionLayer)
                {
                    const JPH::DefaultObjectLayerFilter layerFilter = m_physicsSystem.GetDefaultLayerFilter(
                        ToNativeObjectLayer(request.m_filter.m_collisionLayer));
                    m_physicsSystem.GetNarrowPhaseQuery().CastRay(
                        ray,
                        ToNativeRaycastSettings(request),
                        collector,
                        {},
                        layerFilter,
                        bodyFilter,
                        shapeFilter);
                }
                else
                {
                    m_physicsSystem.GetNarrowPhaseQuery().CastRay(
                        ray,
                        ToNativeRaycastSettings(request),
                        collector,
                        {},
                        {},
                        bodyFilter,
                        shapeFilter);
                }
            };
        if (request.m_filter.m_callback)
        {
            QueryFilterAdapter queryFilter(*this, request.m_filter.m_callback);
            cast(queryFilter, queryFilter);
        }
        else
        {
            cast(JPH::BodyFilter{}, JPH::ShapeFilter{});
        }
        AZStd::sort(
            collector.mHits.begin(),
            collector.mHits.end(),
            [](const JPH::RayCastResult& first, const JPH::RayCastResult& second)
            {
                if (first.mFraction != second.mFraction)
                {
                    return first.mFraction < second.mFraction;
                }
                if (first.mBodyID != second.mBodyID)
                {
                    return first.mBodyID < second.mBodyID;
                }
                return first.mSubShapeID2.GetValue() < second.mSubShapeID2.GetValue();
            });

        QueryResult result;
        if (collector.mHits.size() > AZStd::numeric_limits<AZ::u32>::max())
        {
            result.m_requiredHitCount = AZStd::numeric_limits<AZ::u32>::max();
        }
        else
        {
            result.m_requiredHitCount = static_cast<AZ::u32>(collector.mHits.size());
        }

        const size_t outputCount = AZStd::min(hits.size(), collector.mHits.size());
        for (size_t hitIndex = 0; hitIndex < outputCount; ++hitIndex)
        {
            if (BuildRaycastHit(ray, collector.mHits[hitIndex], hits[result.m_hitCount]))
            {
                ++result.m_hitCount;
            }
        }
        statisticsScope.SetCounts(1, collector.mHits.size(), result.m_hitCount);
        return result;
    }

