        {
            if (BuildRaycastHit(ray, collector.m_hits[hitIndex], hits[result.m_hitCount]))
            {
                ++result.m_hitCount;
            }
        }
        statisticsScope.SetCounts(1, collector.m_hits.size(), result.m_hitCount);
