    bool World::AddStepListener(
        const ExtensionHandle extensionHandle,
        IStepListener* listener)
    {
        if (!listener || m_dispatchingStepListeners.load(AZStd::memory_order_acquire))
        {
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }

        AZStd::lock_guard lock(m_mutex);
        if (m_dispatchingStepListeners.load(AZStd::memory_order_relaxed)
            || AZStd::any_of(
                m_stepListeners.begin(),
                m_stepListeners.end(),
                [extensionHandle](const ExtensionBinding<IStepListener>& binding)
                {
                    return binding.m_handle == extensionHandle;
                }))
        {
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }
        if (!m_system.ClaimExtensionRollbackOwner(extensionHandle, m_handle))
        {
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }
        if (!AdvanceGlobalConfigurationRevision())
        {
            m_system.ReleaseExtensionRollbackOwner(extensionHandle, m_handle);
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }

        m_stepListeners.push_back({
            .m_extension = listener,
            .m_handle = extensionHandle,
        });
        if (m_stepListeners.size() == 1)
        {
            m_physicsSystem.AddStepListener(this);
        }
        return true;
    }

    bool World::RemoveStepListener(
        const ExtensionHandle extensionHandle,
        IStepListener* listener)
    {
        if (!listener || m_dispatchingStepListeners.load(AZStd::memory_order_acquire))
        {
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }

        AZStd::lock_guard lock(m_mutex);
        if (m_dispatchingStepListeners.load(AZStd::memory_order_relaxed))
        {
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }

        const auto listenerIterator = AZStd::find_if(
            m_stepListeners.begin(),
            m_stepListeners.end(),
            [extensionHandle](const ExtensionBinding<IStepListener>& binding)
            {
                return binding.m_handle == extensionHandle;
            });
        if (listenerIterator == m_stepListeners.end())
        {
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }
        if (!AdvanceGlobalConfigurationRevision())
        {
            m_system.ReleaseExtension(extensionHandle);
            return false;
        }

        m_system.ReleaseExtensionRollbackOwner(extensionHandle, m_handle);
        m_stepListeners.erase(listenerIterator);
        m_system.ReleaseExtension(extensionHandle);
        m_system.ReleaseExtension(extensionHandle);
        if (m_stepListeners.empty())
        {
            m_physicsSystem.RemoveStepListener(this);
        }
        return true;
    }

    HairHandle World::CreateHair(
        const HairConfiguration& configuration)
    {
        AZStd::lock_guard lock(m_mutex);
        if (!ValidateWorldTransform(configuration.m_worldTransform)
            || !configuration.m_scalpToHeadTransform.IsFinite()
            || configuration.m_scalpToHeadTransform.GetUniformScale() <= 0.0f
            || !IsSupportedLayer(configuration.m_objectLayer, m_configuration.m_objectLayers.size())
            || !m_system.EnsureHairRuntime())
        {
            return {};
        }

        JPH::RefConst<JPH::HairSettings> settings;
        if (!m_system.AcquireHairDefinition(configuration.m_definitionHandle, settings))
        {
            return {};
        }

        if (!m_hairComputeQueue)
        {
            m_hairComputeQueue = CreateHairComputeQueue(*m_jobSystem);
        }

        auto hair = AZStd::make_unique<NativeHair>(
            settings,
            ToNativePosition(configuration.m_worldTransform.m_position, m_configuration.m_origin),
            ToNativeRotation(configuration.m_worldTransform.m_rotation),
            ToNativeObjectLayer(configuration.m_objectLayer));
        hair->SetScalpToHead(ToNativeTransform(configuration.m_scalpToHeadTransform));

        if (!hair->Init(m_system.m_hairRuntime->m_computeSystem))
        {
            AZ_Error("Jolt", false, "Failed to allocate the hair instance compute buffers.");
            m_system.ReleaseHairDefinition(configuration.m_definitionHandle);
            return {};
        }

        AZ::u32 hairIndex = 0;
        const HairHandle hairHandle = ReserveWorldMemberSlot<HairHandle>(m_hairSlots, m_freeHairSlots, hairIndex);
        if (!hairHandle)
        {
            m_system.ReleaseHairDefinition(configuration.m_definitionHandle);
            return {};
        }

        HairSlot& slot = m_hairSlots[hairIndex];
        slot.m_hair = AZStd::move(hair);
        slot.m_worldTransform = configuration.m_worldTransform;
        slot.m_definitionHandle = configuration.m_definitionHandle;
        slot.m_objectLayer = configuration.m_objectLayer;
        slot.m_initialized = false;
        slot.m_teleported = true;
        return hairHandle;
    }

    bool World::DestroyHair(
        const HairHandle hairHandle)
    {
        AZStd::lock_guard lock(m_mutex);
        Internal::WorldMemberHandleParts parts;
        HairSlot* slot = FindHair(hairHandle);
        if (!slot || !Internal::DecodeWorldMemberHandle(hairHandle, parts))
        {
            return false;
        }

        m_system.ReleaseHairDefinition(slot->m_definitionHandle);
        Internal::ReleaseHandleSlot(m_hairSlots, m_freeHairSlots, parts.m_index);
        return true;
    }

    bool World::IsValid(
        const HairHandle hairHandle) const
    {
        AZStd::lock_guard lock(m_mutex);
        return FindHair(hairHandle);
    }

    bool World::SetHairTransform(
        const HairHandle hairHandle,
        const WorldTransform& worldTransform,
        const bool teleport)
    {
        AZStd::lock_guard lock(m_mutex);
        HairSlot* slot = FindHair(hairHandle);
        if (!slot || !ValidateWorldTransform(worldTransform))
        {
            return false;
        }

        slot->m_hair->SetPosition(ToNativePosition(worldTransform.m_position, m_configuration.m_origin));
        slot->m_hair->SetRotation(ToNativeRotation(worldTransform.m_rotation));
        slot->m_worldTransform = worldTransform;
        if (teleport)
        {
            slot->m_hair->OnTeleported();
            slot->m_teleported = true;
        }
        return true;
    }

    bool World::SetHairScalpToHeadTransform(
        const HairHandle hairHandle,
        const AZ::Transform& scalpToHeadTransform)
    {
        AZStd::lock_guard lock(m_mutex);
        HairSlot* slot = FindHair(hairHandle);
        if (!slot
            || !scalpToHeadTransform.IsFinite()
            || scalpToHeadTransform.GetUniformScale() <= 0.0f
            || !AdvanceConfigurationRevision())
        {
            return false;
        }

        slot->m_hair->SetScalpToHead(ToNativeTransform(scalpToHeadTransform));
        slot->m_hair->OnTeleported();
        slot->m_teleported = true;
        return true;
    }

    bool World::UpdateHair(
        const HairHandle hairHandle,
        const float deltaTime,
        const AZ::Transform& jointToHair,
        const AZStd::span<const AZ::Transform> jointModelTransforms)
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::UpdateHair");
        AZStd::lock_guard lock(m_mutex);
        HairSlot* slot = FindHair(hairHandle);
        if (!slot)
        {
            return false;
        }

        if (!UpdateHairUnlocked(*slot, deltaTime, jointToHair, jointModelTransforms))
        {
            return false;
        }

        return true;
    }

    bool World::EnableHairAutoUpdate(
        const HairHandle hairHandle,
        const AZ::Transform& jointToHair,
        const AZStd::span<const AZ::Transform> jointModelTransforms)
    {
        AZStd::lock_guard lock(m_mutex);
        HairSlot* slot = FindHair(hairHandle);
        if (!slot || !jointToHair.IsFinite())
        {
            return false;
        }

        const JPH::HairSettings* settings = slot->m_hair->GetHairSettings();
        if (jointModelTransforms.size() != settings->mScalpInverseBindPose.size())
        {
            return false;
        }
        for (const AZ::Transform& transform : jointModelTransforms)
        {
            if (!transform.IsFinite())
            {
                return false;
            }
        }

        if (slot->m_autoUpdateState
            && slot->m_autoUpdateState->m_jointToHair == jointToHair
            && AZStd::equal(
                slot->m_autoUpdateState->m_jointModelTransforms.begin(),
                slot->m_autoUpdateState->m_jointModelTransforms.end(),
                jointModelTransforms.begin(),
                jointModelTransforms.end()))
        {
            return true;
        }
        if (!AdvanceConfigurationRevision())
        {
            return false;
        }

        if (!slot->m_autoUpdateState)
        {
            slot->m_autoUpdateState = AZStd::make_unique<HairAutoUpdateState>();
        }
        slot->m_autoUpdateState->m_jointToHair = jointToHair;
        slot->m_autoUpdateState->m_jointModelTransforms.assign(
            jointModelTransforms.begin(),
            jointModelTransforms.end());
        return true;
    }

    bool World::DisableHairAutoUpdate(
        const HairHandle hairHandle)
    {
        AZStd::lock_guard lock(m_mutex);
        HairSlot* slot = FindHair(hairHandle);
        if (!slot)
        {
            return false;
        }
        if (!slot->m_autoUpdateState)
        {
            return true;
        }
        if (!AdvanceConfigurationRevision())
        {
            return false;
        }

        slot->m_autoUpdateState.reset();
        return true;
    }

    bool World::UpdateHairUnlocked(
        HairSlot& slot,
        const float deltaTime,
        const AZ::Transform& jointToHair,
        const AZStd::span<const AZ::Transform> jointModelTransforms)
    {
        if (!AZ::IsFiniteFloat(deltaTime)
            || deltaTime < 0.0f
            || !jointToHair.IsFinite())
        {
            return false;
        }

        const JPH::HairSettings* settings = slot.m_hair->GetHairSettings();
        if (jointModelTransforms.size() != settings->mScalpInverseBindPose.size())
        {
            return false;
        }
        for (const AZ::Transform& transform : jointModelTransforms)
        {
            if (!transform.IsFinite())
            {
                return false;
            }
        }

        AZ::u64 startNanoseconds = 0;
        const bool collectStatistics = IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Hair);
        if (collectStatistics)
        {
            startNanoseconds = GetSteadyNanoseconds();
        }

        m_hairJointTransforms.clear();
        m_hairJointTransforms.reserve(jointModelTransforms.size());
        for (const AZ::Transform& transform : jointModelTransforms)
        {
            m_hairJointTransforms.push_back(ToNativeTransform(transform));
        }

        const JPH::Mat44* jointTransforms = nullptr;
        if (!m_hairJointTransforms.empty())
        {
            jointTransforms = m_hairJointTransforms.data();
        }
        slot.m_hair->Update(
            deltaTime,
            ToNativeTransform(jointToHair),
            jointTransforms,
            m_physicsSystem,
            *m_system.m_hairRuntime->m_shaders,
            m_system.m_hairRuntime->m_computeSystem,
            m_hairComputeQueue);
        slot.m_initialized = true;
        slot.m_teleported = false;
        if (collectStatistics)
        {
            m_performanceStatistics.m_hairUpdateCount.fetch_add(1, AZStd::memory_order_relaxed);
            m_performanceStatistics.m_hairUpdateNanoseconds.fetch_add(
                GetSteadyNanoseconds() - startNanoseconds,
                AZStd::memory_order_relaxed);
        }
        return true;
    }

    bool World::GetHairState(
        const HairHandle hairHandle,
        HairState& state) const
    {
        AZStd::lock_guard lock(m_mutex);
        const HairSlot* slot = FindHair(hairHandle);
        if (!slot)
        {
            return false;
        }

        const JPH::HairSettings* settings = slot->m_hair->GetHairSettings();
        state = {
            .m_worldTransform = slot->m_worldTransform,
            .m_scalpToHeadTransform = FromNativeTransform(slot->m_hair->GetScalpToHeadTransform()),
            .m_renderVertexCount = aznumeric_cast<AZ::u32>(settings->mRenderVertices.size()),
            .m_simulationVertexCount = aznumeric_cast<AZ::u32>(settings->mSimVertices.size()),
            .m_scalpVertexCount = aznumeric_cast<AZ::u32>(settings->mScalpVertices.size()),
            .m_gridCellCount = aznumeric_cast<AZ::u32>(settings->mNeutralDensity.size()),
            .m_gridSizeX = settings->mGridSize.GetX(),
            .m_gridSizeY = settings->mGridSize.GetY(),
            .m_gridSizeZ = settings->mGridSize.GetZ(),
            .m_teleported = slot->m_teleported,
        };
        return true;
    }

    bool World::GetHairReadback(
        const HairHandle hairHandle,
        const HairReadbackBuffers& buffers,
        HairReadbackResult& result) const
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::GetHairReadback");
        AZStd::lock_guard lock(m_mutex);
        const HairSlot* slot = FindHair(hairHandle);
        if (!slot || !slot->m_initialized)
        {
            return false;
        }

        AZ::u64 startNanoseconds = 0;
        const bool collectStatistics = IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Hair);
        if (collectStatistics)
        {
            startNanoseconds = GetSteadyNanoseconds();
        }

        JPH::Hair* hair = slot->m_hair.get();
        const JPH::HairSettings* settings = hair->GetHairSettings();

        const AZ::u32 requiredVertexCount = aznumeric_cast<AZ::u32>(settings->mSimVertices.size());
        const AZ::u32 copiedVertexCount =
            AZStd::min(requiredVertexCount, aznumeric_cast<AZ::u32>(buffers.m_vertexStates.size()));
        const AZ::u32 requiredRenderPositionCount = aznumeric_cast<AZ::u32>(settings->mRenderVertices.size());
        const AZ::u32 copiedRenderPositionCount =
            AZStd::min(requiredRenderPositionCount, aznumeric_cast<AZ::u32>(buffers.m_renderPositions.size()));
        const AZ::u32 requiredScalpPositionCount = aznumeric_cast<AZ::u32>(settings->mScalpVertices.size());
        const AZ::u32 copiedScalpPositionCount =
            AZStd::min(requiredScalpPositionCount, aznumeric_cast<AZ::u32>(buffers.m_scalpPositions.size()));
        const AZ::u32 requiredGridCellCount = aznumeric_cast<AZ::u32>(settings->mNeutralDensity.size());
        const AZ::u32 copiedGridCellCount =
            AZStd::min(requiredGridCellCount, aznumeric_cast<AZ::u32>(buffers.m_gridCells.size()));

        result = {
            .m_vertexStates = {
                .m_hitCount = copiedVertexCount,
                .m_requiredHitCount = requiredVertexCount,
            },
            .m_renderPositions = {
                .m_hitCount = copiedRenderPositionCount,
                .m_requiredHitCount = requiredRenderPositionCount,
            },
            .m_scalpPositions = {
                .m_hitCount = copiedScalpPositionCount,
                .m_requiredHitCount = requiredScalpPositionCount,
            },
            .m_gridCells = {
                .m_hitCount = copiedGridCellCount,
                .m_requiredHitCount = requiredGridCellCount,
            },
        };

        if (copiedVertexCount == 0
            && copiedRenderPositionCount == 0
            && copiedScalpPositionCount == 0
            && copiedGridCellCount == 0)
        {
            if (collectStatistics)
            {
                m_performanceStatistics.m_hairReadbackCount.fetch_add(1, AZStd::memory_order_relaxed);
                m_performanceStatistics.m_hairReadbackNanoseconds.fetch_add(
                    GetSteadyNanoseconds() - startNanoseconds,
                    AZStd::memory_order_relaxed);
            }
            return true;
        }

        hair->ReadBackGPUState(m_hairComputeQueue);
        hair->LockReadBackBuffers();

        const JPH::Float3* nativePositions = hair->GetPositions();
        const JPH::Quat* nativeRotations = hair->GetRotations();
        const JPH::StridedPtr<const JPH::Float3> nativeVelocities = hair->GetVelocities();
        const JPH::StridedPtr<const JPH::Float3> nativeAngularVelocities = hair->GetAngularVelocities();
        HairVertexState* vertexStates = buffers.m_vertexStates.data();
        for (AZ::u32 vertexIndex = 0; vertexIndex < copiedVertexCount; ++vertexIndex)
        {
            vertexStates[vertexIndex] = {
                .m_localPosition = FromNativeVector(JPH::Vec3(nativePositions[vertexIndex])),
                .m_localRotation = FromNativeRotation(nativeRotations[vertexIndex]),
                .m_localLinearVelocity = FromNativeVector(JPH::Vec3(nativeVelocities[vertexIndex])),
                .m_localAngularVelocity = FromNativeVector(JPH::Vec3(nativeAngularVelocities[vertexIndex])),
            };
        }

        if (copiedRenderPositionCount > 0
            || copiedScalpPositionCount > 0
            || copiedGridCellCount > 0)
        {
            const JPH::Float3* nativeRenderPositions = hair->GetRenderPositions();
            AZ::Vector3* renderPositions = buffers.m_renderPositions.data();
            for (AZ::u32 positionIndex = 0; positionIndex < copiedRenderPositionCount; ++positionIndex)
            {
                renderPositions[positionIndex] =
                    FromNativeVector(JPH::Vec3(nativeRenderPositions[positionIndex]));
            }

            const JPH::Float3* nativeScalpPositions = hair->GetScalpVertices();
            AZ::Vector3* scalpPositions = buffers.m_scalpPositions.data();
            for (AZ::u32 positionIndex = 0; positionIndex < copiedScalpPositionCount; ++positionIndex)
            {
                scalpPositions[positionIndex] =
                    FromNativeVector(JPH::Vec3(nativeScalpPositions[positionIndex]));
            }

            const JPH::Float4* nativeGridCells = hair->GetGridVelocityAndDensity();
            HairGridCellState* gridCells = buffers.m_gridCells.data();
            for (AZ::u32 cellIndex = 0; cellIndex < copiedGridCellCount; ++cellIndex)
            {
                gridCells[cellIndex] = {
                    .m_velocityAndDensity = AZ::Vector4::CreateFromFloat4(
                        &nativeGridCells[cellIndex].x),
                };
            }
        }

        hair->UnlockReadBackBuffers();
        if (collectStatistics)
        {
            const AZ::u64 copiedBytes = static_cast<AZ::u64>(copiedVertexCount) * sizeof(HairVertexState)
                + static_cast<AZ::u64>(copiedRenderPositionCount) * sizeof(AZ::Vector3)
                + static_cast<AZ::u64>(copiedScalpPositionCount) * sizeof(AZ::Vector3)
                + static_cast<AZ::u64>(copiedGridCellCount) * sizeof(HairGridCellState);
            m_performanceStatistics.m_hairReadbackBytes.fetch_add(copiedBytes, AZStd::memory_order_relaxed);
            m_performanceStatistics.m_hairReadbackCount.fetch_add(1, AZStd::memory_order_relaxed);
            m_performanceStatistics.m_hairReadbackNanoseconds.fetch_add(
                GetSteadyNanoseconds() - startNanoseconds,
                AZStd::memory_order_relaxed);
        }
        return true;
    }

    QueryResult World::GetHairVertexStates(
        const HairHandle hairHandle,
        const AZStd::span<HairVertexState> states) const
    {
        HairReadbackBuffers buffers;
        buffers.m_vertexStates = states;
        HairReadbackResult result;
        if (!GetHairReadback(hairHandle, buffers, result))
        {
            return {};
        }

        return result.m_vertexStates;
    }

