    void World::OnContactRemoved(
        const JPH::CharacterVirtual* character,
        const JPH::BodyID& bodyId,
        const JPH::SubShapeID& subShapeId)
    {
        if (!character)
        {
            return;
        }

        VirtualCharacterHandle characterHandle;
        VirtualCharacterSlot* slot = FindVirtualCharacter(*character, characterHandle);
        if (!slot || !slot->m_contactCallbacks.m_extension)
        {
            return;
        }

        const VirtualCharacterSlot::ContactProvenance provenance =
            TakeVirtualCharacterContactProvenance(
                *slot,
                bodyId.GetIndexAndSequenceNumber(),
                subShapeId.GetValue(),
                false);
        BodyHandle bodyHandle = provenance.m_bodyHandle;
        if (!bodyHandle)
        {
            [[maybe_unused]] const bool found = FindBodyHandle(bodyId, bodyHandle);
        }
        slot->m_contactCallbacks.m_extension->OnContactRemoved(
            characterHandle,
            bodyHandle,
            SubShapeId(subShapeId.GetValue()));
    }

    void World::OnContactSolve(
        const JPH::CharacterVirtual* character,
        const JPH::BodyID& bodyId,
        const JPH::SubShapeID& subShapeId,
        const JPH::RVec3Arg contactPosition,
        const JPH::Vec3Arg contactNormal,
        const JPH::Vec3Arg contactVelocity,
        const JPH::PhysicsMaterial* contactMaterial,
        const JPH::Vec3Arg characterVelocity,
        JPH::Vec3& newCharacterVelocity)
    {
        if (!character)
        {
            return;
        }

        VirtualCharacterHandle characterHandle;
        VirtualCharacterSlot* slot = FindVirtualCharacter(*character, characterHandle);
        BodyHandle bodyHandle;
        if (!slot
            || !slot->m_contactCallbacks.m_extension
            || !FindBodyHandle(bodyId, bodyHandle))
        {
            return;
        }

        const VirtualCharacterContactSolve contact = {
            .m_position = FromNativePosition(contactPosition, m_configuration.m_origin),
            .m_characterVelocity = FromNativeVector(characterVelocity),
            .m_contactNormal = FromNativeVector(contactNormal),
            .m_contactVelocity = FromNativeVector(contactVelocity),
            .m_bodyHandle = bodyHandle,
            .m_materialHandle = m_system.FindMaterialHandle(contactMaterial),
            .m_subShapeId = SubShapeId(subShapeId.GetValue()),
        };
        AZ::Vector3 callbackVelocity = FromNativeVector(newCharacterVelocity);
        slot->m_contactCallbacks.m_extension->OnContactSolve(
            characterHandle,
            contact,
            callbackVelocity);
        if (callbackVelocity.IsFinite())
        {
            newCharacterVelocity = ToNativeVector(callbackVelocity);
        }
    }

