    void World::OnCharacterContactRemoved(
        const JPH::CharacterVirtual* character,
        const JPH::CharacterID& otherCharacterId,
        const JPH::SubShapeID& subShapeId)
    {
        if (!character)
        {
            return;
        }

        VirtualCharacterHandle characterHandle;
        VirtualCharacterSlot* slot = FindVirtualCharacter(*character, characterHandle);
        if (!slot || !slot->m_contactCallbacks.m_extension)
        {
            return;
        }

        const VirtualCharacterSlot::ContactProvenance provenance =
            TakeVirtualCharacterContactProvenance(
                *slot,
                otherCharacterId.GetValue(),
                subShapeId.GetValue(),
                true);
        VirtualCharacterHandle otherCharacterHandle = provenance.m_characterHandle;
        if (!otherCharacterHandle)
        {
            const auto handleEntry = m_virtualCharacterHandlesById.find(otherCharacterId.GetValue());
            if (handleEntry != m_virtualCharacterHandlesById.end())
            {
                otherCharacterHandle = handleEntry->second;
            }
        }
        slot->m_contactCallbacks.m_extension->OnCharacterContactRemoved(
            characterHandle,
            otherCharacterHandle,
            SubShapeId(subShapeId.GetValue()));
    }

    void World::OnCharacterContactSolve(
        const JPH::CharacterVirtual* character,
        const JPH::CharacterVirtual* otherCharacter,
        const JPH::SubShapeID& subShapeId,
        const JPH::RVec3Arg contactPosition,
        const JPH::Vec3Arg contactNormal,
        const JPH::Vec3Arg contactVelocity,
        const JPH::PhysicsMaterial* contactMaterial,
        const JPH::Vec3Arg characterVelocity,
        JPH::Vec3& newCharacterVelocity)
    {
        if (!character || !otherCharacter)
        {
            return;
        }

        VirtualCharacterHandle characterHandle;
        VirtualCharacterSlot* slot = FindVirtualCharacter(*character, characterHandle);
        const VirtualCharacterHandle otherCharacterHandle =
            GetVirtualCharacterHandle(*otherCharacter);
        if (!slot || !slot->m_contactCallbacks.m_extension || !otherCharacterHandle)
        {
            return;
        }

        const VirtualCharacterContactSolve contact = {
            .m_position = FromNativePosition(contactPosition, m_configuration.m_origin),
            .m_characterVelocity = FromNativeVector(characterVelocity),
            .m_contactNormal = FromNativeVector(contactNormal),
            .m_contactVelocity = FromNativeVector(contactVelocity),
            .m_materialHandle = m_system.FindMaterialHandle(contactMaterial),
            .m_characterHandle = otherCharacterHandle,
            .m_subShapeId = SubShapeId(subShapeId.GetValue()),
        };
        AZ::Vector3 callbackVelocity = FromNativeVector(newCharacterVelocity);
        slot->m_contactCallbacks.m_extension->OnCharacterContactSolve(
            characterHandle,
            contact,
            callbackVelocity);
        if (callbackVelocity.IsFinite())
        {
            newCharacterVelocity = ToNativeVector(callbackVelocity);
        }
    }

    void World::CollideBodies(
        const JPH::Body& firstBody,
        const JPH::Body& secondBody,
        const JPH::Mat44& firstCenterOfMassTransform,
        const JPH::Mat44& secondCenterOfMassTransform,
        JPH::CollideShapeSettings& settings,
        JPH::CollideShapeCollector& collector,
        const JPH::ShapeFilter& shapeFilter)
    {
        const BodyHandle firstBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(firstBody.GetUserData());
        const BodyHandle secondBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(secondBody.GetUserData());
        const BodySlot* firstBodySlot = FindBody(firstBodyHandle);
        const BodySlot* secondBodySlot = FindBody(secondBodyHandle);
        if (!m_bodyPairCollider.m_extension
            || !firstBodySlot
            || !secondBodySlot
            || firstBodySlot->m_bodyId != firstBody.GetID()
            || secondBodySlot->m_bodyId != secondBody.GetID())
        {
            JPH::PhysicsSystem::sDefaultSimCollideBodyVsBody(
                firstBody,
                secondBody,
                firstCenterOfMassTransform,
                secondCenterOfMassTransform,
                settings,
                collector,
                shapeFilter);
            return;
        }

        const auto makeParticipant =
            [this](
                const JPH::Body& body,
                const BodyHandle bodyHandle,
                const BodySlot& slot)
            {
                return BodyCollisionParticipant{
                    .m_centerOfMassTransform = {
                        .m_position = FromNativePosition(
                            body.GetCenterOfMassPosition(),
                            m_configuration.m_origin),
                        .m_rotation = FromNativeRotation(body.GetRotation()),
                    },
                    .m_entityId = slot.m_entityId,
                    .m_bodyHandle = bodyHandle,
                    .m_shapeHandle = slot.m_shapeHandle,
                    .m_objectLayer = ObjectLayer{
                        aznumeric_cast<ObjectLayer::ValueType>(body.GetObjectLayer() + 1),
                    },
                    .m_kind = slot.m_kind,
                    .m_motionType = FromNativeMotionType(body.GetMotionType()),
                    .m_isActive = body.IsActive(),
                    .m_isSensor = body.IsSensor(),
                };
            };
        const BodyPairCollisionInput input = {
            .m_first = makeParticipant(firstBody, firstBodyHandle, *firstBodySlot),
            .m_second = makeParticipant(secondBody, secondBodyHandle, *secondBodySlot),
        };
        const BodyPairCollisionSettings callbackSettings = FromNativeBodyPairCollisionSettings(settings);
        NativeBodyPairCollisionCollector callbackCollector(
            *this,
            firstBody,
            secondBody,
            firstCenterOfMassTransform,
            secondCenterOfMassTransform,
            settings,
            collector,
            shapeFilter);
        m_bodyPairCollider.m_extension->Collide(input, callbackSettings, callbackCollector);
    }

    void World::OnStep(
        const JPH::PhysicsStepListenerContext& context)
    {
        if (m_stepListeners.empty() || context.mPhysicsSystem != &m_physicsSystem)
        {
            return;
        }

        const StepInformation information = {
            .m_deltaTime = context.mDeltaTime,
            .m_isFirst = context.mIsFirstStep,
            .m_isLast = context.mIsLastStep,
        };
        StepContext stepContext(*this);
        m_dispatchingStepListeners.store(true, AZStd::memory_order_release);
        for (const ExtensionBinding<IStepListener>& listener : m_stepListeners)
        {
            listener.m_extension->OnStep(information, stepContext);
        }
        m_dispatchingStepListeners.store(false, AZStd::memory_order_release);
    }

    JPH::ValidateResult World::OnContactValidate(
        const JPH::Body& firstBody,
        const JPH::Body& secondBody,
        const JPH::RVec3Arg baseOffset,
        const JPH::CollideShapeResult& collision)
    {
        if (!m_contactCallbacks.m_extension)
        {
            return JPH::ValidateResult::AcceptAllContactsForThisBodyPair;
        }

        const BodyHandle firstBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(firstBody.GetUserData());
        const BodyHandle secondBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(secondBody.GetUserData());
        const BodySlot* firstBodySlot = FindBody(firstBodyHandle);
        const BodySlot* secondBodySlot = FindBody(secondBodyHandle);
        if (!firstBodySlot
            || !secondBodySlot
            || firstBodySlot->m_bodyId != firstBody.GetID()
            || secondBodySlot->m_bodyId != secondBody.GetID())
        {
            return JPH::ValidateResult::RejectAllContactsForThisBodyPair;
        }

        const ContactValidation contact = {
            .m_positionOnFirstBody = FromNativePosition(
                baseOffset + collision.mContactPointOn1,
                m_configuration.m_origin),
            .m_positionOnSecondBody = FromNativePosition(
                baseOffset + collision.mContactPointOn2,
                m_configuration.m_origin),
            .m_penetrationAxis = FromNativeVector(collision.mPenetrationAxis),
            .m_firstBodyHandle = firstBodyHandle,
            .m_secondBodyHandle = secondBodyHandle,
            .m_firstShapeHandle = firstBodySlot->m_shapeHandle,
            .m_secondShapeHandle = secondBodySlot->m_shapeHandle,
            .m_firstSubShapeId = SubShapeId(collision.mSubShapeID1.GetValue()),
            .m_secondSubShapeId = SubShapeId(collision.mSubShapeID2.GetValue()),
            .m_penetrationDepth = collision.mPenetrationDepth,
        };
        switch (m_contactCallbacks.m_extension->OnContactValidate(contact))
        {
        case ContactDecision::AcceptAllForPair:
            return JPH::ValidateResult::AcceptAllContactsForThisBodyPair;
        case ContactDecision::Accept:
            return JPH::ValidateResult::AcceptContact;
        case ContactDecision::Reject:
            return JPH::ValidateResult::RejectContact;
        case ContactDecision::RejectAllForPair:
            return JPH::ValidateResult::RejectAllContactsForThisBodyPair;
        case ContactDecision::None:
        default:
            return JPH::ValidateResult::RejectAllContactsForThisBodyPair;
        }
    }

    void World::OnContactAdded(
        const JPH::Body& firstBody,
        const JPH::Body& secondBody,
        const JPH::ContactManifold& manifold,
        JPH::ContactSettings& settings)
    {
        ProcessContact(firstBody, secondBody, manifold, settings, EventPhase::Begin);
    }

    void World::OnContactPersisted(
        const JPH::Body& firstBody,
        const JPH::Body& secondBody,
        const JPH::ContactManifold& manifold,
        JPH::ContactSettings& settings)
    {
        ProcessContact(firstBody, secondBody, manifold, settings, EventPhase::Persist);
    }

    void World::OnContactRemoved(
        const JPH::SubShapeIDPair& subShapePair)
    {
        ContactEvent event;
        {
            ContactProducerLock lock(
                m_eventMutex,
                m_performanceStatistics,
                IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Events));
            const auto contactIterator = m_contactCache.find(subShapePair);
            if (contactIterator == m_contactCache.end())
            {
                return;
            }

            event = contactIterator->second;
            event.m_firstPoint = 0;
            event.m_pointCount = 0;
            event.m_phase = EventPhase::End;
            if (m_configuration.m_collectContactEvents)
            {
                const size_t previousCapacity = m_pendingContactEvents.capacity();
                m_pendingContactEvents.push_back(event);
                if (m_pendingContactEvents.capacity() > previousCapacity)
                {
                    lock.RecordStorageGrowth(1);
                }
            }
            m_contactCache.erase(contactIterator);
        }

        if (m_contactCallbacks.m_extension)
        {
            m_contactCallbacks.m_extension->OnContactRemoved(event);
        }
    }

    JPH::SoftBodyValidateResult World::OnSoftBodyContactValidate(
        const JPH::Body& softBody,
        const JPH::Body& otherBody,
        JPH::SoftBodyContactSettings& settings)
    {
        if (!m_softBodyContactCallbacks.m_extension)
        {
            return JPH::SoftBodyValidateResult::AcceptContact;
        }

        const BodyHandle softBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(softBody.GetUserData());
        const BodyHandle otherBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(otherBody.GetUserData());
        const BodySlot* softBodySlot = FindBody(softBodyHandle);
        const BodySlot* otherBodySlot = FindBody(otherBodyHandle);
        if (!softBodySlot
            || !otherBodySlot
            || softBodySlot->m_bodyId != softBody.GetID()
            || otherBodySlot->m_bodyId != otherBody.GetID())
        {
            return JPH::SoftBodyValidateResult::RejectContact;
        }

        SoftBodyContactSettings callbackSettings = {
            .m_softBodyInverseMassScale = settings.mInvMassScale1,
            .m_otherBodyInverseMassScale = settings.mInvMassScale2,
            .m_otherBodyInverseInertiaScale = settings.mInvInertiaScale2,
            .m_isSensor = settings.mIsSensor,
        };
        const SoftBodyContactDecision decision = m_softBodyContactCallbacks.m_extension->OnContactValidate(
            softBodyHandle,
            otherBodyHandle,
            callbackSettings);
        if (decision != SoftBodyContactDecision::Accept
            || !AZ::IsFiniteFloat(callbackSettings.m_softBodyInverseMassScale)
            || callbackSettings.m_softBodyInverseMassScale < 0.0f
            || !AZ::IsFiniteFloat(callbackSettings.m_otherBodyInverseMassScale)
            || callbackSettings.m_otherBodyInverseMassScale < 0.0f
            || !AZ::IsFiniteFloat(callbackSettings.m_otherBodyInverseInertiaScale)
            || callbackSettings.m_otherBodyInverseInertiaScale < 0.0f)
        {
            return JPH::SoftBodyValidateResult::RejectContact;
        }

        settings.mInvMassScale1 = callbackSettings.m_softBodyInverseMassScale;
        settings.mInvMassScale2 = callbackSettings.m_otherBodyInverseMassScale;
        settings.mInvInertiaScale2 = callbackSettings.m_otherBodyInverseInertiaScale;
        settings.mIsSensor = callbackSettings.m_isSensor;
        return JPH::SoftBodyValidateResult::AcceptContact;
    }

    void World::OnSoftBodyContactAdded(
        const JPH::Body& softBody,
        const JPH::SoftBodyManifold& manifold)
    {
        if (!m_softBodyContactCallbacks.m_extension)
        {
            return;
        }

        const BodyHandle softBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(softBody.GetUserData());
        const BodySlot* softBodySlot = FindBody(softBodyHandle);
        if (!softBodySlot
            || softBodySlot->m_bodyId != softBody.GetID()
            || softBodySlot->m_kind != BodyKind::Soft)
        {
            return;
        }

        const NativeSoftBodyContactManifold contactManifold(
            manifold,
            softBody.GetCenterOfMassTransform(),
            m_physicsSystem.GetBodyInterfaceNoLock(),
            m_configuration.m_origin);
        m_softBodyContactCallbacks.m_extension->OnContactAdded(softBodyHandle, contactManifold);
    }

    bool World::ShouldCollide(
        const JPH::Body& firstBody,
        const JPH::Shape* firstShape,
        const JPH::SubShapeID& firstSubShapeId,
        const JPH::Body& secondBody,
        const JPH::Shape* secondShape,
        const JPH::SubShapeID& secondSubShapeId) const
    {
        if (!m_simulationShapeFilter.m_extension)
        {
            return true;
        }

        const BodyHandle firstBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(firstBody.GetUserData());
        const BodyHandle secondBodyHandle =
            Internal::HandleAccess::FromValue<BodyHandle>(secondBody.GetUserData());
        const BodySlot* firstBodySlot = FindBody(firstBodyHandle);
        const BodySlot* secondBodySlot = FindBody(secondBodyHandle);
        if (!firstShape
            || !secondShape
            || !firstBodySlot
            || !secondBodySlot
            || firstBodySlot->m_bodyId != firstBody.GetID()
            || secondBodySlot->m_bodyId != secondBody.GetID())
        {
            return false;
        }

        const SimulationShape first = {
            .m_bodyHandle = firstBodyHandle,
            .m_rootShapeHandle = firstBodySlot->m_shapeHandle,
            .m_subShapeId = SubShapeId(firstSubShapeId.GetValue()),
            .m_kind = FromNativeShapeKind(firstShape->GetSubType()),
        };
        const SimulationShape second = {
            .m_bodyHandle = secondBodyHandle,
            .m_rootShapeHandle = secondBodySlot->m_shapeHandle,
            .m_subShapeId = SubShapeId(secondSubShapeId.GetValue()),
            .m_kind = FromNativeShapeKind(secondShape->GetSubType()),
        };
        return m_simulationShapeFilter.m_extension->ShouldCollide(first, second);
    }

    void World::ProcessContact(
        const JPH::Body& firstBody,
        const JPH::Body& secondBody,
        const JPH::ContactManifold& manifold,
        JPH::ContactSettings& settings,
        const EventPhase phase)
    {
        if (m_contactCallbacks.m_extension)
        {
            const BodyHandle firstBodyHandle =
                Internal::HandleAccess::FromValue<BodyHandle>(firstBody.GetUserData());
            const BodyHandle secondBodyHandle =
                Internal::HandleAccess::FromValue<BodyHandle>(secondBody.GetUserData());
            const BodySlot* firstBodySlot = FindBody(firstBodyHandle);
            const BodySlot* secondBodySlot = FindBody(secondBodyHandle);
            if (firstBodySlot
                && secondBodySlot
                && firstBodySlot->m_bodyId == firstBody.GetID()
                && secondBodySlot->m_bodyId == secondBody.GetID())
            {
                const NativeContactManifold contactManifold(
                    manifold,
                    firstBody,
                    secondBody,
                    firstBodyHandle,
                    secondBodyHandle,
                    firstBodySlot->m_shapeHandle,
                    secondBodySlot->m_shapeHandle,
                    m_configuration.m_origin);
                ContactSettings callbackSettings = FromNativeContactSettings(settings);
                if (phase == EventPhase::Begin)
                {
                    m_contactCallbacks.m_extension->OnContactAdded(contactManifold, callbackSettings);
                }
                else
                {
                    m_contactCallbacks.m_extension->OnContactPersisted(contactManifold, callbackSettings);
                }
                [[maybe_unused]] const bool settingsApplied =
                    ApplyContactSettings(callbackSettings, settings);
            }
        }

        if (m_configuration.m_collectContactEvents || m_contactCallbacks.m_extension)
        {
            RecordContact(firstBody, secondBody, manifold, phase);
        }
    }

    void World::RecordContact(
        const JPH::Body& firstBody,
        const JPH::Body& secondBody,
        const JPH::ContactManifold& manifold,
        const EventPhase phase)
    {
        const BodyHandle firstBodyHandle = Internal::HandleAccess::FromValue<BodyHandle>(firstBody.GetUserData());
        const BodyHandle secondBodyHandle = Internal::HandleAccess::FromValue<BodyHandle>(secondBody.GetUserData());
        const BodySlot* firstBodySlot = FindBody(firstBodyHandle);
        const BodySlot* secondBodySlot = FindBody(secondBodyHandle);
        if (!firstBodySlot
            || !secondBodySlot
            || firstBodySlot->m_bodyId != firstBody.GetID()
            || secondBodySlot->m_bodyId != secondBody.GetID())
        {
            return;
        }

        const JPH::PhysicsMaterial* firstMaterial = firstBody.GetShape()->GetMaterial(manifold.mSubShapeID1);
        const JPH::PhysicsMaterial* secondMaterial = secondBody.GetShape()->GetMaterial(manifold.mSubShapeID2);
        ContactEvent event = {
            .m_firstBodyHandle = firstBodyHandle,
            .m_secondBodyHandle = secondBodyHandle,
            .m_firstShapeHandle = firstBodySlot->m_shapeHandle,
            .m_secondShapeHandle = secondBodySlot->m_shapeHandle,
            .m_firstMaterialHandle = m_system.FindMaterialHandle(firstMaterial),
            .m_secondMaterialHandle = m_system.FindMaterialHandle(secondMaterial),
            .m_firstSubShapeId = SubShapeId(manifold.mSubShapeID1.GetValue()),
            .m_secondSubShapeId = SubShapeId(manifold.mSubShapeID2.GetValue()),
            .m_normal = FromNativeVector(manifold.mWorldSpaceNormal),
            .m_penetrationDepth = manifold.mPenetrationDepth,
            .m_phase = phase,
        };

        const JPH::SubShapeIDPair pair(
            firstBody.GetID(),
            manifold.mSubShapeID1,
            secondBody.GetID(),
            manifold.mSubShapeID2);
        ContactProducerLock lock(
            m_eventMutex,
            m_performanceStatistics,
            IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Events));
        if (m_pendingContactPoints.size() > AZStd::numeric_limits<AZ::u32>::max()
            || manifold.mRelativeContactPointsOn1.size()
                > AZStd::numeric_limits<AZ::u32>::max() - m_pendingContactPoints.size())
        {
            if (IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Events))
            {
                m_performanceStatistics.m_droppedEventCount.fetch_add(1, AZStd::memory_order_relaxed);
            }
            return;
        }

        const size_t previousContactEventCapacity = m_pendingContactEvents.capacity();
        const size_t previousContactPointCapacity = m_pendingContactPoints.capacity();
        const size_t previousContactCacheBucketCount = m_contactCache.bucket_count();
        if (m_configuration.m_collectContactEvents)
        {
            event.m_firstPoint = static_cast<AZ::u32>(m_pendingContactPoints.size());
            event.m_pointCount = static_cast<AZ::u32>(manifold.mRelativeContactPointsOn1.size());
            for (JPH::uint pointIndex = 0; pointIndex < manifold.mRelativeContactPointsOn1.size(); ++pointIndex)
            {
                m_pendingContactPoints.push_back({
                    .m_positionOnFirstBody = FromNativePosition(
                        manifold.GetWorldSpaceContactPointOn1(pointIndex),
                        m_configuration.m_origin),
                    .m_positionOnSecondBody = FromNativePosition(
                        manifold.GetWorldSpaceContactPointOn2(pointIndex),
                        m_configuration.m_origin),
                });
            }
            m_pendingContactEvents.push_back(event);
        }
        event.m_firstPoint = 0;
        event.m_pointCount = 0;
        m_contactCache.insert_or_assign(pair, event);

        AZ::u64 growthCount = 0;
        if (m_pendingContactEvents.capacity() > previousContactEventCapacity)
        {
            ++growthCount;
        }
        if (m_pendingContactPoints.capacity() > previousContactPointCapacity)
        {
            ++growthCount;
        }
        if (m_contactCache.bucket_count() > previousContactCacheBucketCount)
        {
            ++growthCount;
        }
        lock.RecordStorageGrowth(growthCount);
    }

    void World::PublishEvents()
    {
        JOLT_PROFILE_SCOPE(Physics, "Jolt::World::PublishEvents");
        if (!m_bodyMoveHandles.empty())
        {
            constexpr AZ::u32 invalidIndex = AZStd::numeric_limits<AZ::u32>::max();
            const JPH::uint32 activeRigidBodyCount =
                m_physicsSystem.GetNumActiveBodies(JPH::EBodyType::RigidBody);
            const JPH::uint32 activeSoftBodyCount =
                m_physicsSystem.GetNumActiveBodies(JPH::EBodyType::SoftBody);
            const size_t activeBodyCount = activeRigidBodyCount + activeSoftBodyCount;

            const auto gatherBodies =
                [this](
                    const JPH::BodyID* bodyIds,
                    const int bodyCount,
                    const bool requireActive)
                {
                    JPH::BodyLockMultiRead bodyLock(
                        m_physicsSystem.GetBodyLockInterface(),
                        bodyIds,
                        bodyCount);
                    for (int bodyIndex = 0; bodyIndex < bodyCount; ++bodyIndex)
                    {
                        const JPH::Body* body = bodyLock.GetBody(bodyIndex);
                        if (!body || (requireActive && !body->IsActive()))
                        {
                            continue;
                        }

                        const BodyHandle bodyHandle =
                            Internal::HandleAccess::FromValue<BodyHandle>(body->GetUserData());
                        const BodySlot* slot = FindBody(bodyHandle);
                        if (!slot
                            || slot->m_bodyId != body->GetID()
                            || slot->m_moveEventIndex == invalidIndex)
                        {
                            continue;
                        }

                        m_pendingBodyMoveEvents.push_back({
                            .m_transform = {
                                .m_position = FromNativePosition(body->GetPosition(), m_configuration.m_origin),
                                .m_rotation = FromNativeRotation(body->GetRotation()),
                            },
                            .m_bodyHandle = bodyHandle,
                            .m_entityId = slot->m_entityId,
                        });
                    }
                };

            if (m_bodyMoveHandles.size() <= activeBodyCount)
            {
                m_bodyIdScratch.clear();
                m_bodyIdScratch.reserve(m_bodyMoveHandles.size());
                for (const BodyHandle bodyHandle : m_bodyMoveHandles)
                {
                    const BodySlot* slot = FindBody(bodyHandle);
                    AZ_Assert(slot, "Body move subscription handle is inconsistent.");
                    if (slot)
                    {
                        m_bodyIdScratch.push_back(slot->m_bodyId);
                    }
                }
                gatherBodies(
                    m_bodyIdScratch.data(),
                    aznumeric_cast<int>(m_bodyIdScratch.size()),
                    true);
            }
            else
            {
                gatherBodies(
                    m_physicsSystem.GetActiveBodiesUnsafe(JPH::EBodyType::RigidBody),
                    aznumeric_cast<int>(activeRigidBodyCount),
                    false);
                gatherBodies(
                    m_physicsSystem.GetActiveBodiesUnsafe(JPH::EBodyType::SoftBody),
                    aznumeric_cast<int>(activeSoftBodyCount),
                    false);
            }
        }

        for (size_t characterIndex = 0; characterIndex < m_virtualCharacterSlots.size(); ++characterIndex)
        {
            const VirtualCharacterSlot& slot = m_virtualCharacterSlots[characterIndex];
            if (!slot.m_character || !slot.m_autoUpdateConfiguration)
            {
                continue;
            }

            m_pendingVirtualCharacterMoveEvents.push_back({
                .m_transform = {
                    .m_position = FromNativePosition(slot.m_character->GetPosition(), m_configuration.m_origin),
                    .m_rotation = FromNativeRotation(slot.m_character->GetRotation()),
                },
                .m_characterHandle = Internal::MakeWorldMemberHandle<VirtualCharacterHandle>(
                    m_worldIndex,
                    aznumeric_cast<AZ::u32>(characterIndex),
                    slot.m_generation),
                .m_entityId = slot.m_entityId,
            });
        }

        EventBatch eventBatch = m_eventBatchPool->Acquire();
        AZ_Assert(eventBatch, "The event-batch pool rejected a live world.");
        if (!eventBatch)
        {
            AZ_Error("Jolt", false, "The event-batch identity domain is exhausted.");
            return;
        }

        EventBatch previousBatch;
        AZStd::lock_guard lock(m_eventMutex);
        AZStd::sort(
            m_pendingContactEvents.begin(),
            m_pendingContactEvents.end(),
            [](const ContactEvent& first, const ContactEvent& second)
            {
                if (first.m_firstBodyHandle != second.m_firstBodyHandle)
                {
                    return first.m_firstBodyHandle < second.m_firstBodyHandle;
                }
                if (first.m_secondBodyHandle != second.m_secondBodyHandle)
                {
                    return first.m_secondBodyHandle < second.m_secondBodyHandle;
                }
                if (first.m_firstSubShapeId.GetValue() != second.m_firstSubShapeId.GetValue())
                {
                    return first.m_firstSubShapeId.GetValue() < second.m_firstSubShapeId.GetValue();
                }
                if (first.m_secondSubShapeId.GetValue() != second.m_secondSubShapeId.GetValue())
                {
                    return first.m_secondSubShapeId.GetValue() < second.m_secondSubShapeId.GetValue();
                }
                return first.m_phase < second.m_phase;
            });
        AZStd::sort(
            m_pendingActivationEvents.begin(),
            m_pendingActivationEvents.end(),
            [](const ActivationEvent& first, const ActivationEvent& second)
            {
                if (first.m_bodyHandle != second.m_bodyHandle)
                {
                    return first.m_bodyHandle < second.m_bodyHandle;
                }
                return first.m_state < second.m_state;
            });
        AZStd::sort(
            m_pendingBodyMoveEvents.begin(),
            m_pendingBodyMoveEvents.end(),
            [](const BodyMoveEvent& first, const BodyMoveEvent& second)
            {
                return first.m_bodyHandle < second.m_bodyHandle;
            });
        AZStd::sort(
            m_pendingVirtualCharacterMoveEvents.begin(),
            m_pendingVirtualCharacterMoveEvents.end(),
            [](const VirtualCharacterMoveEvent& first, const VirtualCharacterMoveEvent& second)
            {
                return first.m_characterHandle < second.m_characterHandle;
            });

        const size_t publishedEventCount = m_pendingContactEvents.size()
            + m_pendingActivationEvents.size()
            + m_pendingBodyMoveEvents.size()
            + m_pendingVirtualCharacterMoveEvents.size();
        if (IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::Events))
        {
            m_performanceStatistics.m_publishedEventCount.fetch_add(
                publishedEventCount,
                AZStd::memory_order_relaxed);
            UpdateMaximum(
                m_performanceStatistics.m_eventHighWaterCount,
                aznumeric_cast<AZ::u64>(publishedEventCount));
        }
        if (IsPerformanceStatisticsEnabled(PerformanceStatisticsFlags::NarrowPhase))
        {
            m_performanceStatistics.m_contactEventCount.fetch_add(
                m_pendingContactEvents.size(),
                AZStd::memory_order_relaxed);
            m_performanceStatistics.m_contactPointCount.fetch_add(
                m_pendingContactPoints.size(),
                AZStd::memory_order_relaxed);
        }

        AZ::u64 nextEventSequence = m_eventSequence + 1;
        if (nextEventSequence == 0)
        {
            ++nextEventSequence;
        }
        const bool published = m_eventBatchPool->Publish(
            eventBatch,
            nextEventSequence,
            m_pendingContactEvents,
            m_pendingContactPoints,
            m_pendingActivationEvents,
            m_pendingBodyMoveEvents,
            m_pendingVirtualCharacterMoveEvents);
        AZ_Assert(published, "A Jolt event batch must belong to its world pool.");
        if (!published)
        {
            return;
        }
        m_eventSequence = nextEventSequence;
        m_pendingContactEvents.clear();
        m_pendingContactPoints.clear();
        m_pendingActivationEvents.clear();
        m_pendingBodyMoveEvents.clear();
        m_pendingVirtualCharacterMoveEvents.clear();
        previousBatch = AZStd::move(m_publishedEvents);
        m_publishedEvents = AZStd::move(eventBatch);
    }

    const World::ShapeSlot* World::FindShape(
        const ShapeHandle shapeHandle) const
    {
        Internal::WorldMemberHandleParts parts;
        if (!Internal::DecodeWorldMemberHandle(shapeHandle, parts)
            || parts.m_worldIndex != m_worldIndex
            || parts.m_index >= m_shapeSlots.size())
        {
            return nullptr;
        }

        const ShapeSlot& slot = m_shapeSlots[parts.m_index];
        if (slot.m_generation != parts.m_generation || !slot.m_shape)
        {
            return nullptr;
        }

        return &slot;
    }

    World::ShapeSlot* World::FindShape(
        const ShapeHandle shapeHandle)
    {
        return const_cast<ShapeSlot*>(static_cast<const World&>(*this).FindShape(shapeHandle));
    }

