    const JPH::CompoundShape* World::FindCompound(
        const ShapeHandle shapeHandle) const
    {
        const ShapeSlot* slot = FindShape(shapeHandle);
        if (!slot
            || (slot->m_shape->GetSubType() != JPH::EShapeSubType::MutableCompound
                && slot->m_shape->GetSubType() != JPH::EShapeSubType::StaticCompound))
        {
            return nullptr;
        }

        return static_cast<const JPH::CompoundShape*>(slot->m_shape.GetPtr());
    }

