    const JPH::HeightFieldShape* World::FindHeightfield(
        const ShapeHandle shapeHandle) const
    {
        const ShapeSlot* slot = FindShape(shapeHandle);
        if (!slot)
        {
            return nullptr;
        }

        const JPH::Shape* shape = slot->m_shape.GetPtr();
        if (shape->GetSubType() == JPH::EShapeSubType::RotatedTranslated)
        {
            shape = static_cast<const JPH::DecoratedShape*>(shape)->GetInnerShape();
        }
        if (shape->GetSubType() != JPH::EShapeSubType::HeightField)
        {
            return nullptr;
        }

        return static_cast<const JPH::HeightFieldShape*>(shape);
    }

