    void World::NotifyShapeChanged(
        const ShapeHandle shapeHandle,
        const JPH::Vec3& previousCenterOfMass,
        const bool updateMassProperties,
        const bool activateBodies)
    {
        const ShapeSlot* shapeSlot = FindShape(shapeHandle);
        if (!shapeSlot)
        {
            return;
        }

        const JPH::Vec3 centerOfMassDelta = shapeSlot->m_shape->GetCenterOfMass() - previousCenterOfMass;
        JPH::EActivation activation = JPH::EActivation::DontActivate;
        if (activateBodies)
        {
            activation = JPH::EActivation::Activate;
        }

        JPH::BodyInterface& bodyInterface = m_physicsSystem.GetBodyInterface();
        for (AZ::u32 bodyIndex = 0; bodyIndex < m_bodySlots.size(); ++bodyIndex)
        {
            const BodySlot& bodySlot = m_bodySlots[bodyIndex];
            if (bodySlot.m_bodyId.IsInvalid()
                || bodySlot.m_kind != BodyKind::Rigid
                || bodySlot.m_shapeHandle != shapeHandle)
            {
                continue;
            }

            const BodyHandle bodyHandle = Internal::MakeWorldMemberHandle<BodyHandle>(
                m_worldIndex,
                bodyIndex,
                bodySlot.m_generation);
            bodyInterface.NotifyShapeChanged(
                bodySlot.m_bodyId,
                previousCenterOfMass,
                updateMassProperties,
                activation);

            for (ConstraintSlot& constraintSlot : m_constraintSlots)
            {
                if (constraintSlot.m_constraint
                    && (constraintSlot.m_firstBodyHandle == bodyHandle
                        || constraintSlot.m_secondBodyHandle == bodyHandle))
                {
                    constraintSlot.m_constraint->NotifyShapeChanged(bodySlot.m_bodyId, centerOfMassDelta);
                }
            }

            if (bodySlot.m_vehicleHandle)
            {
                VehicleSlot* vehicleSlot = FindVehicle(bodySlot.m_vehicleHandle);
                if (vehicleSlot)
                {
                    vehicleSlot->m_constraint->NotifyShapeChanged(bodySlot.m_bodyId, centerOfMassDelta);
                }
            }
        }
    }

